  t_admin_processes_h: "Procesy i usługi",
  t_admin_performance_h: "Monitor wydajności",
  t_admin_storage_h: "Analizator pamięci masowej",
  t_admin_events_h: "Podgląd zdarzeń",
  t_admin_registry_h: "Edytor rejestru",
